const BITS = {};
/* The baked map for a level or biome key (level.biome is the key). */
export const stageMap = level => STAGE_MAPS[typeof level === 'string' ? level : level?.biome] || null;
/* Is world point (x, y) blocked on this level's map? Off-map is blocked. */
export function stageBlocked(level, x, y) {
  const m = stageMap(level); if (!m) return false;
  const c = m.collision, gx = Math.floor(x / c.cell), gy = Math.floor(y / c.cell);
  if (gx < 0 || gy < 0 || gx >= c.w || gy >= c.h) return true;
  const key = typeof level === 'string' ? level : level.biome;
  const bits = BITS[key] || (BITS[key] = typeof atob === 'function' ? Uint8Array.from(atob(c.bits), ch => ch.charCodeAt(0)) : Uint8Array.from(Buffer.from(c.bits, 'base64')));
  const i = gy * c.w + gx; return !!(bits[i >> 3] & (1 << (i & 7)));
}
